INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Windows Server immer teurer als Linux?', 2, '[{"text": "Ja", "correct": true, "because": "Lizenzkosten vs. Open Source"}, {"text": "Nein", "correct": false, "because": "Selten günstiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System wähle ich für eine kostengünstige Webserver-Lösung?', 3, '[{"text": "Linux", "correct": true, "because": "Kostenlos und flexibel"}, {"text": "Windows Server", "correct": false, "because": "Lizenzkosten höher"}, {"text": "Ältere Versionen beider", "correct": false, "because": "Sicherheitsrisiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Betriebssystem für Virtualisierung geeignet?', 5, '[{"text": "Hypervisor-Unterstützung", "correct": true, "because": "Effiziente VM-Verwaltung"}, {"text": "Skalierbarkeit", "correct": true, "because": "Viele VMs möglich"}, {"text": "Grafische Oberfläche", "correct": false, "because": "Sekundär"}, {"text": "Hohe Lizenzkosten", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Linux ist immer Open Source. b) Windows Server unterstützt nur AD.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, mehr als AD möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Systems für einen Dateiserver?', 4, '[{"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Kompatibilität", "correct": false, "because": "Clients müssen zugreifen"}, {"text": "Gaming-Features", "correct": true, "because": "Irrelevant für Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Linux mehr Befehlszeilenkenntnisse braucht als Windows Server?', 2, '[{"text": "Ja", "correct": true, "because": "CLI oft dominanter"}, {"text": "Nein", "correct": false, "because": "GUI bei Linux optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für einen Domain-Controller entscheidend?', 3, '[{"text": "Active Directory", "correct": true, "because": "Zentrale Verwaltung"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht nötig"}, {"text": "Kostenlosigkeit", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Linux für Server?', 5, '[{"text": "Kostenfreiheit", "correct": true, "because": "Keine Lizenzgebühren"}, {"text": "Anpassbarkeit", "correct": true, "because": "Open Source erlaubt Änderungen"}, {"text": "Einfache GUI", "correct": false, "because": "Nicht primär"}, {"text": "Gaming-Support", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Windows Server ist stabiler als Linux. b) Linux ist nur für Experten. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) kontextabhängig, b) auch für Anfänger geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "Beides zu pauschal"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) nicht immer"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Datenbankserver?', 4, '[{"text": "Hohe Stabilität", "correct": false, "because": "Kritisch für Betrieb"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Lasten"}, {"text": "Integrierte Spiele", "correct": true, "because": "Irrelevant für Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt Windows Server mehr Hardware als Linux?', 2, '[{"text": "Nein", "correct": true, "because": "Linux hat breite Treiberunterstützung"}, {"text": "Ja", "correct": false, "because": "Windows oft eingeschränkter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für einen Mailserver wichtig?', 4, '[{"text": "Sicherheitsfeatures", "correct": true, "because": "Schutz vor Angriffen"}, {"text": "Hohe Verfügbarkeit", "correct": true, "because": "Dauerbetrieb nötig"}, {"text": "Grafische Tools", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ältere Versionen immer unsicher sind. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Fehlende Updates erhöhen Risiken"}, {"text": "Nein", "correct": false, "because": "Selten sicher ohne Patches"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für einen kleinen Firmenserver?', 3, '[{"text": "Einfache Verwaltung", "correct": true, "because": "Wenig Personal"}, {"text": "Maximale Leistung", "correct": false, "because": "Nicht immer nötig"}, {"text": "Kostenlose Updates", "correct": false, "because": "Wichtig, aber sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Linux ist ressourcenschonend. b) Windows Server braucht immer eine GUI.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Core-Modus möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Windows Server für Unternehmen?', 5, '[{"text": "Active Directory", "correct": true, "because": "Zentrale Benutzerverwaltung"}, {"text": "Breite Software-Kompatibilität", "correct": true, "because": "Viele Tools laufen nativ"}, {"text": "Kostenfreiheit", "correct": false, "because": "Lizenzkosten nötig"}, {"text": "Einfache CLI", "correct": false, "because": "GUI-dominiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für einen Webserver unwichtig?', 3, '[{"text": "Sicherheitsupdates", "correct": false, "because": "Schutz ist essenziell"}, {"text": "Stabilität", "correct": false, "because": "Dauerbetrieb nötig"}, {"text": "3D-Grafikunterstützung", "correct": true, "because": "Nicht benötigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Linux für Container besser geeignet als Windows Server?', 3, '[{"text": "Ja", "correct": true, "because": "Leichter und nativer Support"}, {"text": "Nein", "correct": false, "because": "Windows schwerer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Windows Server ältere Versionen gut unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Rückwärtskompatibilität stark"}, {"text": "Nein", "correct": false, "because": "Oft kompatibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System wähle ich für eine GUI-freie Installation?', 4, '[{"text": "Linux", "correct": true, "because": "Flexibel ohne GUI"}, {"text": "Windows Server", "correct": false, "because": "Core-Modus möglich, aber komplexer"}, {"text": "Beides gleich", "correct": false, "because": "Linux einfacher"}]');
